--

CREATE INDEX idx_vehicles_route_position ON public.vehicles USING btree (assigned_route_id, is_active, last_position_update) WHERE ((is_active = true) AND (current_latitude IS NOT NULL) AND (assigned_route_id IS NOT NULL));


--
